import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.vLhlLNVn.js";const y=JSON.parse('{"title":"🏭 MES 制造执行与设备工单","description":"","frontmatter":{},"headers":[],"relativePath":"synergy/mes.md","filePath":"synergy/mes.md"}'),a={name:"synergy/mes.md"};function r(s,t,n,i,c,g){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="🏭-mes-制造执行与设备工单" tabindex="-1">🏭 MES 制造执行与设备工单 <a class="header-anchor" href="#🏭-mes-制造执行与设备工单" aria-label="Permalink to &quot;🏭 MES 制造执行与设备工单&quot;">​</a></h1><p><code>yudao-module-mes</code> 是 MzMedia 面向数字化车间打造的制造执行与设备运维系统，深度融合了物联网传感器报警与现场生产协同。</p><hr><h2 id="_1-六大子系统功能矩阵" tabindex="-1">1. 六大子系统功能矩阵 <a class="header-anchor" href="#_1-六大子系统功能矩阵" aria-label="Permalink to &quot;1. 六大子系统功能矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">子模块</th><th style="text-align:left;">标识</th><th style="text-align:left;">核心定位与业务价值</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>主数据管理</strong></td><td style="text-align:left;"><code>md</code></td><td style="text-align:left;">物料 BOM 清单、SOP 标准作业指导书、SIP 标准检验规程、车间工位工作站与编码规则定义。</td></tr><tr><td style="text-align:left;"><strong>排产与日历</strong></td><td style="text-align:left;"><code>cal</code></td><td style="text-align:left;">生产日历、早中夜三班轮转排程、法定节假日规则与班组人员分配。</td></tr><tr><td style="text-align:left;"><strong>设备台账与维保</strong></td><td style="text-align:left;"><code>dv</code></td><td style="text-align:left;"><strong>设备全生命周期档案、点检计划、保养记录；与 IoT 告警自动联动生成维修工单。</strong></td></tr><tr><td style="text-align:left;"><strong>生产制造流转</strong></td><td style="text-align:left;"><code>pro</code></td><td style="text-align:left;">工艺路线设计、生产工单与流转卡（Card）、工序派工、报工流水与安灯（Andon）一键呼叫。</td></tr><tr><td style="text-align:left;"><strong>全流程质检</strong></td><td style="text-align:left;"><code>qc</code></td><td style="text-align:left;">来料检验 (IQC)、过程检验 (IPQC)、出货质检 (OQC)、质检方案与缺陷代码归因库。</td></tr><tr><td style="text-align:left;"><strong>车间物料条码</strong></td><td style="text-align:left;"><code>wm</code></td><td style="text-align:left;">生产领退料、物料单品 SN 序列号追踪、批次追溯与线边仓动态盘点。</td></tr></tbody></table><hr><h2 id="_2-iot-设备告警与车间工单闭环" tabindex="-1">2. IoT 设备告警与车间工单闭环 <a class="header-anchor" href="#_2-iot-设备告警与车间工单闭环" aria-label="Permalink to &quot;2. IoT 设备告警与车间工单闭环&quot;">​</a></h2><p>当安装在加工中心机床上的振动传感器或温升传感器检测到持续超出警戒阈值时：</p><ol><li><code>yudao-module-iot</code> 触发场景联动规则；</li><li>自动调用 <code>yudao-module-mes</code> 中的设备维保接口，在 <code>dv</code> 模块自动生成一张“紧急维修工单”；</li><li>同时触发车间 <strong>Andon 安灯呼叫</strong>，生产调度大屏对应工位亮红灯；</li><li>生产主管在审批通过后，系统自动在 <code>pro</code> 模块将该工位的后续待加工批次转移至备用产线，避免批量废品。</li></ol>',9)])])}const x=e(a,[["render",r]]);export{y as __pageData,x as default};
